// The Google Sheets node emits one item per row plus a row_number field.
// Keep the FIRST row whose Status column is empty - row_number lets the update
// node at the end mark exactly this row as done.
const rows = $input.all().map((i) => i.json);
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const row = rows.find((r) => isEmpty(r.Status));
if (!row) {
  return [{ json: { found: false, source: 'sheet', checked: rows.length } }];
}
return [{
  json: {
    found: true,
    source: 'sheet',
    row,
    rowNumber: row.row_number,
    recordId: null,
    checked: rows.length,
  },
}];

// Airtable returns { records: [{ id, fields }] }. Take the first record whose
// Status field is empty and that this workflow has not already rendered.
// Airtable mode does not write back, so the rendered ids are remembered in
// workflow static data instead - and only AFTER a successful render (see
// Run summary), so a failed render retries the same listing next time.
const res = $input.first().json;
const status = Number(res && res.statusCode);
const body = (res && res.body) || {};

if (!Number.isFinite(status) || status === 0) {
  throw new Error('Could not reach the Airtable API. Check airtableBaseId / airtableTable in Config and the Bearer credential on this node.');
}
if (status >= 400) {
  throw new Error('Airtable answered HTTP ' + status + ': ' + JSON.stringify(body).slice(0, 300));
}

const records = Array.isArray(body.records) ? body.records : [];
const staticData = $getWorkflowStaticData('global');
const seen = Array.isArray(staticData.renderedListingIds) ? staticData.renderedListingIds : [];
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';

const hit = records.find((r) => r && r.fields && isEmpty(r.fields.Status) && !seen.includes(String(r.id)));
if (!hit) {
  return [{ json: { found: false, source: 'airtable', checked: records.length } }];
}
return [{
  json: {
    found: true,
    source: 'airtable',
    row: hit.fields,
    rowNumber: null,
    recordId: hit.id,
    checked: records.length,
  },
}];

// Every listing already has a Status value (or Airtable returned nothing new),
// so there is nothing to render today. This is a normal, successful outcome -
// not an error.
const picked = $input.first().json;
return [{
  json: {
    rendered: false,
    source: picked.source || 'sheet',
    reason: picked.source === 'airtable'
      ? 'No Airtable record with an empty Status that has not been rendered yet.'
      : 'No sheet row with an empty Status column. Add fresh listing rows.',
    rowsChecked: picked.checked,
  },
}];

// One shape for both sources. Column names are matched case-insensitively and
// with a couple of common spellings, so "Sq Ft", "SqFt" and "sqft" all work.
const picked = $input.first().json;
const row = picked.row || {};

const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();

// Build a lower-cased lookup once: sheet headers and Airtable field names are
// user-typed and casing drifts.
const lookup = {};
for (const key of Object.keys(row)) {
  lookup[key.toLowerCase().replace(/[^a-z0-9]/g, '')] = row[key];
}
const get = (...names) => {
  for (const n of names) {
    const v = lookup[n.toLowerCase().replace(/[^a-z0-9]/g, '')];
    if (v != null && clean(v) !== '') return clean(v);
  }
  return '';
};

const address = get('Address');
const city = get('City');
const price = get('Price');
const beds = get('Beds', 'Bedrooms');
const baths = get('Baths', 'Bathrooms');
const sqft = get('Sqft', 'SqFt', 'Sq Ft', 'SquareFeet', 'Area');

const photos = [];
for (let i = 1; i <= 5; i += 1) {
  const url = get('Photo' + i, 'Image' + i);
  if (/^https?:\/\//i.test(url)) photos.push(url);
}

const where = picked.source === 'airtable'
  ? 'Airtable record ' + picked.recordId
  : 'Sheet row ' + picked.rowNumber;

const missing = [];
if (!address) missing.push('Address');
if (photos.length < 2) missing.push('at least 2 public https photo URLs in Photo1..Photo5 (found ' + photos.length + ')');
if (missing.length) {
  throw new Error(where + ' is missing ' + missing.join(' and ') + '. Fill it in, or put anything in Status to skip this listing.');
}

return [{
  json: {
    source: picked.source || 'sheet',
    rowNumber: picked.rowNumber == null ? null : picked.rowNumber,
    recordId: picked.recordId == null ? null : picked.recordId,
    address,
    city,
    price,
    beds,
    baths,
    sqft,
    photos,
    agentName: get('AgentName', 'Agent'),
    agentPhone: get('AgentPhone', 'Phone'),
    agentPhotoUrl: get('AgentPhotoUrl', 'AgentPhoto'),
  },
}];

// The music bed is optional. An unreachable URL, an HTTP error or a file over
// the plan's audio cap renders the video WITHOUT music instead of failing the
// run - a missing soundtrack is a much smaller problem than a missing video.
const cfg = $('Config').first().json;
const listing = $('Normalize listing').first().json;
const res = $input.first().json;

const maxBytes = Number(cfg.maxMusicBytes) || 5242880;
const url = String(cfg.musicUrl || '').trim();

let musicUrl = url;
let reason = null;
let bytes = null;

if (!url) {
  musicUrl = '';
  reason = 'musicUrl is empty in Config';
} else {
  const status = Number(res && res.statusCode);
  const headers = (res && res.headers) || {};
  const len = Number(headers['content-length'] || headers['Content-Length'] || 0);
  bytes = Number.isFinite(len) && len > 0 ? len : null;
  if (!Number.isFinite(status) || status === 0) {
    musicUrl = '';
    reason = 'the music URL was unreachable';
  } else if (status >= 400) {
    musicUrl = '';
    reason = 'the music URL answered HTTP ' + status;
  } else if (bytes && bytes > maxBytes) {
    musicUrl = '';
    reason = 'the music file is ' + Math.round(bytes / 1024) + ' KB, over the ' + Math.round(maxBytes / 1024) + ' KB cap';
  }
}

return [{ json: { ...listing, musicUrl, musicBytes: bytes, musicSkippedReason: reason } }];

// === buildProject — identical to the frame-reviewed standalone builder ===
// Turns ONE normalised listing into a 1080x1920 property reel:
//
//   scene 1      hero    — Photo1 full-bleed under a scrim, story progress rail,
//                          brokerage line, "JUST LISTED" chip, price banner,
//                          address + city, all on a slow cinematic push
//   scenes 2..N  photo   — one per remaining photo (5 photo scenes max), each
//                          spotlighting ONE fact (beds / baths / sq ft) as an
//                          oversized serif numeral with the other facts on a
//                          muted rail; side and push depth alternate so two
//                          consecutive scenes never look the same
//   last scene   agent   — the agent's circular portrait (or a monogram disc),
//                          name, phone, brokerage, CTA pill and contact domain
//
// RENDERER NOTES that shape this design:
//  * `resize` on a media element resolves against the PROJECT canvas, not the
//    element's own box, so it is only safe on full-bleed layers. Every property
//    photo is therefore full-bleed `cover` — never inset, never stretched.
//  * The agent portrait IS inset, so it is drawn as an <img> inside a TEXT
//    element instead: the browser honours object-fit/border-radius, which keeps
//    the aspect ratio correct inside a circle.
//  * `zoom` is a centred push (depth 1..10) over the element's visible window.
//    There is no pan and no zoom-out, so variety comes from alternating depth,
//    alternating transition direction and alternating layout side.
//  * A scene `transition` overlaps its two scenes, so every non-last scene
//    stores duration = visible seconds + transitionDuration.
function buildProject(config, data) {
  const cfg = config || {};
  const clean = function (v) { return String(v == null ? '' : v).replace(/\s+/g, ' ').trim(); };
  const esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };
  const round = function (n) { return Math.round(n * 100) / 100; };

  // ---- colour helpers -----------------------------------------------------
  const hexToRgb = function (hex) {
    let h = String(hex).trim().replace('#', '');
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    const n = parseInt(h, 16);
    if (!Number.isFinite(n) || h.length !== 6) return { r: 198, g: 161, b: 91 };
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  };
  const rgba = function (hex, a) {
    const c = hexToRgb(hex);
    return 'rgba(' + c.r + ',' + c.g + ',' + c.b + ',' + a + ')';
  };
  const lighten = function (hex, t) {
    const c = hexToRgb(hex);
    const f = function (v) { return Math.round(v + (255 - v) * t); };
    const hx = function (v) { return ('0' + v.toString(16)).slice(-2); };
    return '#' + hx(f(c.r)) + hx(f(c.g)) + hx(f(c.b));
  };

  // ---- inputs -------------------------------------------------------------
  const address = clean(data.address);
  const city = clean(data.city);
  if (!address) throw new Error('The listing has no Address.');

  const photos = (Array.isArray(data.photos) ? data.photos : [])
    .map(clean)
    .filter(function (u) { return /^https?:\/\//i.test(u); })
    .slice(0, 5);
  if (photos.length < 2) {
    throw new Error('A listing needs at least 2 photo URLs (found ' + photos.length + '). Fill Photo1..Photo5 with public https image links.');
  }

  const agentName = clean(data.agentName);
  const agentPhone = clean(data.agentPhone);
  const agentPhoto = clean(data.agentPhotoUrl);
  const hasAgentPhoto = /^https?:\/\//i.test(agentPhoto);

  // ---- brand knobs --------------------------------------------------------
  const brandName = clean(cfg.brandName) || 'Your brokerage';
  const listedLabel = (clean(cfg.listedLabel) || 'JUST LISTED').toUpperCase();
  const ctaText = clean(cfg.ctaText) || 'Book a viewing';
  const agentLabel = (clean(cfg.agentLabel) || 'YOUR AGENT').toUpperCase();
  const serifFont = clean(cfg.serifFont) || 'Playfair Display';
  const uiFont = clean(cfg.uiFont) || 'Manrope';
  const ink = clean(cfg.inkColor) || '#14110E';
  const cream = clean(cfg.creamColor) || '#F6F1E8';
  const brand = clean(cfg.brandColor) || '#1F3D34';
  const accent = clean(cfg.accentColor) || '#C6A15B';
  const currency = clean(cfg.currencySymbol) || '$';

  // contactUrl -> bare host, so the card never shows a raw https:// prefix.
  const contactRaw = clean(cfg.contactUrl);
  const contactDomain = contactRaw
    .replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .replace(/[?#].*$/, '');

  // Ken Burns depth: 1 = static, 1.14 = a slow 14% push over the whole scene.
  const depthRaw = Number(cfg.kenBurnsDepth);
  const depth = Number.isFinite(depthRaw) ? Math.min(1.6, Math.max(1, depthRaw)) : 1.14;
  // The gentler alternate push. Both are >= 1 so the clamp in the renderer
  // never turns one of them into a static frame by surprise.
  const depthSoft = round(1 + (depth - 1) * 0.55);

  // ---- number formatting --------------------------------------------------
  // A value that is nothing but digits/dots/commas/spaces is OURS to format;
  // anything else (already has a currency symbol, a suffix, a range) is left
  // exactly as the agent typed it.
  const groupInt = function (intStr) {
    return intStr.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  };
  const formatNumeric = function (raw, prefix, suffix) {
    const v = clean(raw);
    if (!v) return '';
    if (!/^[\d.,\s]+$/.test(v)) return v;
    const digits = v.replace(/[,\s]/g, '');
    if (!/^\d+(\.\d+)?$/.test(digits)) return v;
    const parts = digits.split('.');
    const body = groupInt(parts[0]) + (parts[1] ? '.' + parts[1] : '');
    return (prefix || '') + body + (suffix || '');
  };
  const price = formatNumeric(data.price, currency, '');
  const sqft = formatNumeric(data.sqft, '', '');
  const beds = clean(data.beds);
  const baths = clean(data.baths);

  // ---- the fact pool ------------------------------------------------------
  // Only facts the sheet actually carries. Nothing is invented, nothing is
  // rounded up: the numbers on screen are the numbers in the row.
  const facts = [];
  if (beds) facts.push({ key: 'beds', value: beds, label: 'BEDROOMS', short: beds + ' bd' });
  if (baths) facts.push({ key: 'baths', value: baths, label: 'BATHROOMS', short: baths + ' ba' });
  if (sqft) facts.push({ key: 'sqft', value: sqft, label: 'SQUARE FEET', short: sqft + ' sqft' });

  // What each photo scene spotlights, in order. The price joins the rotation
  // at the end so a five-photo listing does not repeat "BEDROOMS" twice; with
  // no facts at all the price carries every scene, and with neither the scene
  // is just the photograph.
  const spotlights = facts.slice();
  if (price) spotlights.push({ key: 'price', value: price, label: 'ASKING PRICE' });

  // ---- greedy wrap estimate ----------------------------------------------
  // Calibrated against the rendered source designs: Playfair Display averages
  // ~0.50em per glyph, the sans UI face ~0.52em.
  const wrapLines = function (text, fontPx, boxPx, avgEm) {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    const words = String(text).split(' ');
    for (let i = 0; i < words.length; i += 1) {
      const w = words[i];
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };

  // ---- timing -------------------------------------------------------------
  const TD = 0.55;
  const heroSeconds = 4.4;
  const photoSeconds = 3.3;
  const agentSeconds = 4.8;
  const photoScenes = photos.length - 1; // scene 1 uses photos[0]
  const totalSeconds = round(heroSeconds + photoScenes * photoSeconds + agentSeconds);
  const sceneCount = photos.length + 1; // every photo scene plus the agent card

  const svgOpen = "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>";

  // ---- story progress rail ------------------------------------------------
  // One segment per scene, the current one filled. Deterministic, no motion —
  // it reads as chapter marks rather than a fake loading bar.
  const progressRail = function (activeIndex) {
    const x0 = 80;
    const total = 920;
    const gap = 10;
    const segW = (total - gap * (sceneCount - 1)) / sceneCount;
    let body = '';
    for (let i = 0; i < sceneCount; i += 1) {
      const x = round(x0 + i * (segW + gap));
      body += "<rect x='" + x + "' y='56' width='" + round(segW) + "' height='4' rx='2' fill='"
        + (i <= activeIndex ? accent : rgba(cream, 0.28)) + "'/>";
    }
    return body;
  };

  // ---- scene 1 — hero -----------------------------------------------------
  const heroDur = round(heroSeconds + TD);

  const addrSize = address.length <= 22 ? 76 : address.length <= 34 ? 64 : address.length <= 48 ? 54 : 46;
  const addrLines = wrapLines(address, addrSize, 900, 0.5);
  const addrH = Math.round(addrLines * addrSize * 1.08);
  const cityTop = 1736;
  const addrTop = cityTop - 20 - addrH;
  // 132 = the price banner's own height (~91 px at 46 px type + 18 px padding)
  // plus a 40 px breath before the address.
  const bannerTop = addrTop - 132;

  // SCRIM CALIBRATION — measured, not guessed. A listing photo can be a dusk
  // exterior or a white-on-white kitchen, so both scrims are tuned for the
  // WORST case (type over pure white): ~0.65 ink under the top rail and ~0.85
  // under the bottom block puts cream above 5:1 and the gold numerals above
  // 4.5:1 on a white wall, and both still read as a soft vignette on a dark
  // exterior. Frame-checked against a bright interior and a dusk exterior.
  const heroScrim = svgOpen
    + "<defs><linearGradient id='relHero' x1='0' y1='0' x2='0' y2='1'>"
    + "<stop offset='0' stop-color='" + ink + "' stop-opacity='0.86'/>"
    + "<stop offset='0.09' stop-color='" + ink + "' stop-opacity='0.5'/>"
    + "<stop offset='0.22' stop-color='" + ink + "' stop-opacity='0.16'/>"
    + "<stop offset='0.52' stop-color='" + ink + "' stop-opacity='0.22'/>"
    + "<stop offset='0.7' stop-color='" + ink + "' stop-opacity='0.66'/>"
    + "<stop offset='0.78' stop-color='" + ink + "' stop-opacity='0.9'/>"
    + "<stop offset='1' stop-color='" + ink + "' stop-opacity='0.98'/></linearGradient></defs>"
    + "<rect width='1080' height='1920' fill='url(#relHero)'/>"
    + progressRail(0)
    // Quiet estate corner brackets — the only ornament in the whole design.
    + "<path d='M80 232 L80 168 L144 168' fill='none' stroke='" + rgba(accent, 0.75) + "' stroke-width='4'/>"
    + "<path d='M1000 232 L1000 168 L936 168' fill='none' stroke='" + rgba(accent, 0.75) + "' stroke-width='4'/>"
    + '</svg>';

  const s1 = {
    id: 'hero',
    duration: heroDur,
    backgroundColor: ink,
    transition: 'smoothleft',
    transitionId: photoScenes > 0 ? 'shot1' : 'agent',
    transitionDuration: TD,
    visuals: [
      {
        type: 'IMAGE', src: photos[0], width: 1080, height: 1920,
        position: 'center-center', resize: 'cover', zoom: { depth: depth },
        track: 0, enterBegin: 0, exitEnd: heroDur,
      },
      {
        type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: heroDur,
        svg: heroScrim,
      },
      {
        type: 'TEXT', x: 540, y: 108, width: 860, anchor: 'top-center', track: 2,
        enterBegin: 0, enterEnd: 0.4, enterAnimation: 'fade', exitEnd: heroDur,
        style: { fontFamily: uiFont, color: cream },
        html: "<div style='text-align:center; color:" + cream + "; font-size:25px; font-weight:700; letter-spacing:9px;'>" + esc(brandName.toUpperCase()) + '</div>',
      },
      {
        // No `width`: a width-less text box is sized to fit-content, and that is
        // what centres an inline-block pill on x=540.
        type: 'TEXT', x: 540, y: 196, anchor: 'top-center', track: 2,
        enterBegin: 0.28, enterEnd: 0.74, enterAnimation: 'smoothdown', exitEnd: heroDur,
        style: { fontFamily: uiFont, color: accent },
        html: "<div style='display:inline-block; background:" + rgba(ink, 0.72) + '; border:1.5px solid ' + rgba(accent, 0.7) + '; color:' + accent + "; border-radius:999px; padding:15px 40px; font-size:26px; font-weight:800; letter-spacing:6px;'>" + esc(listedLabel) + '</div>',
      },
      {
        type: 'TEXT', x: 80, y: addrTop, width: 900, anchor: 'top-left', track: 3,
        enterBegin: 0.7, enterEnd: 1.24, enterAnimation: 'smoothup', exitEnd: heroDur,
        style: { fontFamily: serifFont, color: cream },
        html: "<div style='color:" + cream + '; font-size:' + addrSize + "px; line-height:1.08; font-weight:700;'>" + esc(address) + '</div>',
      },
    ],
  };

  if (price) {
    s1.visuals.push({
      type: 'TEXT', x: 80, y: bannerTop, anchor: 'top-left', track: 3,
      enterBegin: 0.5, enterEnd: 0.98, enterAnimation: 'smoothright', exitEnd: heroDur,
      style: { fontFamily: uiFont, color: cream },
      html: "<div style='display:inline-block; background:" + brand + '; color:' + cream + "; border-radius:8px; padding:18px 38px; font-size:46px; font-weight:800; letter-spacing:1px;'>" + esc(price) + '</div>',
    });
  }
  if (city) {
    s1.visuals.push({
      type: 'TEXT', x: 80, y: cityTop, width: 900, anchor: 'top-left', track: 3,
      enterBegin: 1.05, enterEnd: 1.45, enterAnimation: 'fade', exitEnd: heroDur,
      style: { fontFamily: uiFont, color: accent },
      html: "<div style='color:" + accent + "; font-size:26px; font-weight:700; letter-spacing:7px;'>" + esc(city.toUpperCase()) + '</div>',
    });
  }

  // ---- scenes 2..N — one photo, one fact ---------------------------------
  const scenes = [s1];
  const railLine = facts.map(function (f) { return f.short; }).join('   ·   ');
  // The top rail is one line by contract: 22 px + 6 px tracking fits ~46
  // characters in the 900 px box, so the city is dropped before the address is,
  // and a monster address is cut with an ellipsis rather than allowed to wrap.
  const railFit = function (s) {
    if (s.length <= 44) return s;
    let cut = s.slice(0, 40);
    // Prefer a word boundary. "1400 QUAILWOOD RIDGE BOULEVARD…" reads as a
    // deliberate edit; "…RIDGE BOULEVARD, NORTHEAS…" reads as a bug. The floor
    // stops a single monster word from collapsing the line to nothing — in
    // that case a hard cut is genuinely the better of two bad options.
    const sp = cut.lastIndexOf(' ');
    if (sp >= 24) cut = cut.slice(0, sp);
    return cut.replace(/[\s,.;:·-]+$/, '') + '…';
  };
  const withCity = city ? address + '  ·  ' + city : address;
  const topRailText = withCity.length <= 44 ? withCity : railFit(address);

  for (let i = 1; i < photos.length; i += 1) {
    const isLastPhoto = i === photos.length - 1;
    const dur = round(photoSeconds + TD);
    const onLeft = i % 2 === 1;
    const fact = spotlights.length ? spotlights[(i - 1) % spotlights.length] : null;

    // The spotlight value is bottom-aligned on a fixed baseline (1550), so a
    // one-character "6" and an eleven-character "$12,450,000" sit on the same
    // line and the label below never moves.
    const factChars = fact ? fact.value.length : 0;
    const factSize = factChars <= 6 ? 110 : factChars <= 9 ? 92 : factChars <= 12 ? 76 : 62;
    const factTop = 1550 - factSize;
    const tickTop = factTop + 8;
    const tickH = Math.max(24, factSize - 16);

    const scrim = svgOpen
      + "<defs><linearGradient id='relShot" + i + "' x1='0' y1='0' x2='0' y2='1'>"
      + "<stop offset='0' stop-color='" + ink + "' stop-opacity='0.88'/>"
      + "<stop offset='0.09' stop-color='" + ink + "' stop-opacity='0.52'/>"
      + "<stop offset='0.2' stop-color='" + ink + "' stop-opacity='0.12'/>"
      + "<stop offset='0.56' stop-color='" + ink + "' stop-opacity='0.12'/>"
      + "<stop offset='0.7' stop-color='" + ink + "' stop-opacity='0.62'/>"
      + "<stop offset='0.76' stop-color='" + ink + "' stop-opacity='0.9'/>"
      + "<stop offset='1' stop-color='" + ink + "' stop-opacity='0.99'/></linearGradient></defs>"
      + "<rect width='1080' height='1920' fill='url(#relShot" + i + ")'/>"
      + progressRail(i)
      + '</svg>';

    const s = {
      id: 'shot' + i,
      duration: dur,
      backgroundColor: ink,
      transition: onLeft ? 'smoothleft' : 'smoothright',
      transitionId: isLastPhoto ? 'agent' : 'shot' + (i + 1),
      transitionDuration: TD,
      visuals: [
        {
          type: 'IMAGE', src: photos[i], width: 1080, height: 1920,
          position: 'center-center', resize: 'cover',
          zoom: { depth: onLeft ? depth : depthSoft },
          track: 0, enterBegin: 0, exitEnd: dur,
        },
        {
          type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: dur,
          svg: scrim,
        },
        {
          type: 'TEXT', x: 540, y: 108, width: 900, anchor: 'top-center', track: 2,
          enterBegin: 0, enterEnd: 0.35, enterAnimation: 'fade', exitEnd: dur,
          style: { fontFamily: uiFont, color: cream },
          html: "<div style='text-align:center; color:" + cream + "; font-size:22px; font-weight:700; letter-spacing:6px;'>" + esc(topRailText.toUpperCase()) + '</div>',
        },
      ],
    };

    const align = onLeft ? 'left' : 'right';
    const blockX = onLeft ? 116 : 964;
    const blockAnchor = onLeft ? 'top-left' : 'top-right';

    if (fact) {
      // The accent tick is its own element rather than part of the scrim, so it
      // animates in WITH the numeral. Left in the scrim it would sit alone on
      // screen through the 0.55 s crossfade while the type was still arriving.
      s.visuals.push({
        type: 'SVG', x: onLeft ? 80 : 994, y: tickTop, width: 6, height: tickH, anchor: 'top-left', track: 3,
        enterBegin: 0.22, enterEnd: 0.72, enterAnimation: 'fade', exitEnd: dur,
        svg: "<svg width='6' height='" + tickH + "' viewBox='0 0 6 " + tickH + "' xmlns='http://www.w3.org/2000/svg'><rect width='6' height='" + tickH + "' rx='3' fill='" + accent + "'/></svg>",
      });
      s.visuals.push({
        type: 'TEXT', x: blockX, y: factTop, width: 848, anchor: blockAnchor, track: 3,
        enterBegin: 0.22, enterEnd: 0.72, enterAnimation: onLeft ? 'smoothright' : 'smoothleft', exitEnd: dur,
        style: { fontFamily: serifFont, color: accent },
        html: "<div style='text-align:" + align + '; color:' + accent + '; font-size:' + factSize + "px; line-height:1; font-weight:700;'>" + esc(fact.value) + '</div>',
      });
      s.visuals.push({
        type: 'TEXT', x: blockX, y: 1568, width: 848, anchor: blockAnchor, track: 3,
        enterBegin: 0.38, enterEnd: 0.84, enterAnimation: 'fade', exitEnd: dur,
        style: { fontFamily: uiFont, color: cream },
        html: "<div style='text-align:" + align + '; color:' + cream + "; font-size:30px; font-weight:700; letter-spacing:8px;'>" + esc(fact.label) + '</div>',
      });
    }

    if (railLine) {
      s.visuals.push({
        type: 'TEXT', x: blockX, y: 1662, width: 848, anchor: blockAnchor, track: 3,
        enterBegin: 0.6, enterEnd: 1.0, enterAnimation: 'fade', exitEnd: dur,
        style: { fontFamily: uiFont, color: rgba(cream, 0.72) },
        html: "<div style='text-align:" + align + '; color:' + rgba(cream, 0.72) + "; font-size:26px; font-weight:600; letter-spacing:3px;'>" + esc(railLine) + '</div>',
      });
    }

    scenes.push(s);
  }

  // ---- last scene — the agent card ---------------------------------------
  // A split card: the hero photo keeps the top of the frame (so the reel ends
  // on the property, not on a black slab) and a solid ink panel carries the
  // contact block. The portrait medallion straddles the seam between them.
  const PORTRAIT = 252;      // outer ring diameter of the portrait / monogram

  const nameSize = agentName.length <= 16 ? 62 : agentName.length <= 24 ? 52 : 44;
  const nameLines = wrapLines(agentName || brandName, nameSize, 880, 0.52);
  const nameH = Math.round(nameLines * nameSize * 1.12);

  const LABEL_H = 32;
  const PHONE_H = 46;
  const PILL_H = 100;
  const DOMAIN_H = 34;
  const BRAND_H = 30;

  // Offsets within the contact stack, measured from the "YOUR AGENT" label.
  const dName = LABEL_H + 20;
  const dPhone = dName + nameH + 18;
  const dPill = dPhone + (agentPhone ? PHONE_H : 0) + 48;
  const dDomain = dPill + PILL_H + 40;
  const dBrand = dDomain + (contactDomain ? DOMAIN_H : 0) + 42;
  const stackH = dBrand + BRAND_H;

  // The SEAM follows the content instead of sitting at a fixed height. The
  // portrait hangs a tight HANG above the label so medallion, name and CTA
  // read as ONE block, and the stack lands BOTTOM_MARGIN off the frame edge.
  // A fixed seam left ~250 px of dead panel under a short agent name (the card
  // read top-heavy); centring the stack inside the panel instead fixed the
  // dead space but detached the medallion from the name. Moving the seam does
  // both — and a taller stack simply lifts the seam, which grows the ink panel
  // rather than pushing the brokerage line off the bottom, so no pull-up valve
  // is needed. The clamp keeps the split sane at either extreme.
  const HANG = 64;
  const BOTTOM_MARGIN = 150;
  const SEAM = Math.max(940, Math.min(1120,
    Math.round(1920 - BOTTOM_MARGIN - stackH - HANG - PORTRAIT / 2)));
  const portraitY = SEAM - PORTRAIT / 2;

  const labelY = portraitY + PORTRAIT + HANG;
  const nameY = labelY + dName;
  const phoneY = labelY + dPhone;
  const pillY = labelY + dPill;
  const domainY = labelY + dDomain;
  const brandY = labelY + dBrand;

  // The closing rail restates the listing rather than repeating the city — the
  // last frame is the one people screenshot.
  const endRail = price ? address + '  ·  ' + price : address;
  const endRailText = endRail.length <= 44 ? endRail : railFit(address);

  const agentScrim = svgOpen
    // The gradient lives inside the 1010 px photo band, so its offsets are
    // fractions of THAT rect: 0.17 == y 172, which is where the top rail sits.
    + "<defs><linearGradient id='relEndTop' x1='0' y1='0' x2='0' y2='1'>"
    + "<stop offset='0' stop-color='" + ink + "' stop-opacity='0.9'/>"
    + "<stop offset='0.17' stop-color='" + ink + "' stop-opacity='0.5'/>"
    + "<stop offset='0.34' stop-color='" + ink + "' stop-opacity='0.12'/>"
    + "<stop offset='0.75' stop-color='" + ink + "' stop-opacity='0.2'/>"
    + "<stop offset='1' stop-color='" + ink + "' stop-opacity='0.9'/></linearGradient></defs>"
    + "<rect x='0' y='0' width='1080' height='" + SEAM + "' fill='url(#relEndTop)'/>"
    + "<rect x='0' y='" + SEAM + "' width='1080' height='" + (1920 - SEAM) + "' fill='" + ink + "'/>"
    + "<rect x='0' y='" + (SEAM - 2) + "' width='1080' height='3' fill='" + rgba(accent, 0.65) + "'/>"
    + progressRail(sceneCount - 1)
    + "<path d='M80 232 L80 168 L144 168' fill='none' stroke='" + rgba(accent, 0.75) + "' stroke-width='4'/>"
    + "<path d='M1000 1752 L1000 1816 L936 1816' fill='none' stroke='" + rgba(accent, 0.75) + "' stroke-width='4'/>"
    + '</svg>';

  const sEnd = {
    id: 'agent',
    duration: agentSeconds,
    backgroundColor: ink,
    visuals: [
      {
        type: 'IMAGE', src: photos[0], width: 1080, height: 1920,
        position: 'center-center', resize: 'cover',
        zoom: { depth: depthSoft },
        track: 0, enterBegin: 0, exitEnd: agentSeconds,
      },
      {
        type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: agentSeconds,
        svg: agentScrim,
      },
      {
        type: 'TEXT', x: 540, y: 108, width: 900, anchor: 'top-center', track: 2,
        enterBegin: 0, enterEnd: 0.35, enterAnimation: 'fade', exitEnd: agentSeconds,
        style: { fontFamily: uiFont, color: cream },
        html: "<div style='text-align:center; color:" + cream + "; font-size:22px; font-weight:700; letter-spacing:6px;'>" + esc(endRailText.toUpperCase()) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: labelY, width: 880, anchor: 'top-center', track: 3,
        enterBegin: 0.5, enterEnd: 0.9, enterAnimation: 'fade', exitEnd: agentSeconds,
        style: { fontFamily: uiFont, color: accent },
        html: "<div style='text-align:center; color:" + accent + "; font-size:25px; font-weight:700; letter-spacing:9px;'>" + esc(agentLabel) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: nameY, width: 880, anchor: 'top-center', track: 3,
        enterBegin: 0.65, enterEnd: 1.12, enterAnimation: 'smoothup', exitEnd: agentSeconds,
        style: { fontFamily: serifFont, color: cream },
        html: "<div style='text-align:center; color:" + cream + '; font-size:' + nameSize + "px; line-height:1.12; font-weight:700;'>" + esc(agentName || brandName) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: pillY, anchor: 'top-center', track: 3,
        enterBegin: 1.2, enterEnd: 1.68, enterAnimation: 'circleopen', exitEnd: agentSeconds,
        style: { fontFamily: uiFont, color: cream },
        html: "<div style='display:inline-block; background:" + brand + '; color:' + cream + "; border-radius:999px; padding:27px 64px; font-size:38px; font-weight:800;'>" + esc(ctaText) + '</div>',
      },
    ],
  };

  // The portrait is inset, so it rides inside a TEXT element: the browser keeps
  // the headshot's aspect ratio with object-fit and masks it with a real
  // border-radius. A missing/blank AgentPhotoUrl falls back to a monogram disc.
  if (hasAgentPhoto) {
    const inner = PORTRAIT - 12;
    sEnd.visuals.push({
      type: 'TEXT', x: 540, y: portraitY, anchor: 'top-center', track: 2,
      enterBegin: 0.15, enterEnd: 0.75, enterAnimation: 'circleopen', exitEnd: agentSeconds,
      style: { fontFamily: uiFont, color: cream },
      html: "<div style='width:" + inner + 'px; height:' + inner + "px; padding:6px; border-radius:999px; background:" + accent + ";'>"
        + "<div style='width:" + inner + 'px; height:' + inner + "px; border-radius:999px; overflow:hidden; background:" + rgba(cream, 0.12) + ";'>"
        + "<img src='" + esc(agentPhoto) + "' width='" + inner + "' height='" + inner + "' alt='' style='width:" + inner + 'px; height:' + inner + "px; object-fit:cover; display:block;'/>"
        + '</div></div>',
    });
  } else {
    const initials = (agentName || brandName)
      .split(' ')
      .filter(function (w) { return /[\p{L}\p{N}]/u.test(w); })
      .slice(0, 2)
      .map(function (w) { return (w.match(/[\p{L}\p{N}]/u) || [''])[0].toUpperCase(); })
      .join('') || '?';
    sEnd.visuals.push({
      type: 'SVG', x: 540, y: portraitY, width: PORTRAIT, height: PORTRAIT, anchor: 'top-center', track: 2,
      enterBegin: 0.15, enterEnd: 0.75, enterAnimation: 'circleopen', exitEnd: agentSeconds,
      svg: "<svg width='" + PORTRAIT + "' height='" + PORTRAIT + "' viewBox='0 0 " + PORTRAIT + ' ' + PORTRAIT + "' xmlns='http://www.w3.org/2000/svg'>"
        + "<defs><linearGradient id='relMono' x1='0' y1='0' x2='1' y2='1'>"
        + "<stop offset='0' stop-color='" + accent + "'/><stop offset='1' stop-color='" + lighten(accent, 0.35) + "'/></linearGradient></defs>"
        // Opaque, not tinted: the disc sits ON the seam, so a translucent fill
        // would show the photo through its top half and the panel through its
        // bottom half and read as two halves rather than one medallion.
        + "<circle cx='" + PORTRAIT / 2 + "' cy='" + PORTRAIT / 2 + "' r='" + (PORTRAIT / 2 - 6) + "' fill='" + ink + "'/>"
        + "<circle cx='" + PORTRAIT / 2 + "' cy='" + PORTRAIT / 2 + "' r='" + (PORTRAIT / 2 - 3) + "' fill='none' stroke='" + accent + "' stroke-width='5'/>"
        + "<text x='" + PORTRAIT / 2 + "' y='" + (PORTRAIT / 2 + 30) + "' font-family='Georgia, serif' font-size='86' font-weight='700' fill='url(#relMono)' text-anchor='middle'>" + esc(initials) + '</text>'
        + '</svg>',
    });
  }

  if (agentPhone) {
    sEnd.visuals.push({
      type: 'TEXT', x: 540, y: phoneY, width: 880, anchor: 'top-center', track: 3,
      enterBegin: 0.9, enterEnd: 1.3, enterAnimation: 'fade', exitEnd: agentSeconds,
      style: { fontFamily: uiFont, color: accent },
      html: "<div style='text-align:center; color:" + accent + "; font-size:38px; font-weight:700; letter-spacing:2px;'>" + esc(agentPhone) + '</div>',
    });
  }
  if (contactDomain) {
    sEnd.visuals.push({
      type: 'TEXT', x: 540, y: domainY, width: 880, anchor: 'top-center', track: 3,
      enterBegin: 1.5, enterEnd: 1.9, enterAnimation: 'fade', exitEnd: agentSeconds,
      style: { fontFamily: uiFont, color: rgba(cream, 0.66) },
      html: "<div style='text-align:center; color:" + rgba(cream, 0.66) + "; font-size:26px; font-weight:600; letter-spacing:5px;'>" + esc(contactDomain.toUpperCase()) + '</div>',
    });
  }
  sEnd.visuals.push({
    type: 'TEXT', x: 540, y: brandY, width: 880, anchor: 'top-center', track: 3,
    enterBegin: 1.7, enterEnd: 2.05, enterAnimation: 'fade', exitEnd: agentSeconds,
    style: { fontFamily: uiFont, color: rgba(cream, 0.5) },
    html: "<div style='text-align:center; color:" + rgba(cream, 0.5) + "; font-size:23px; font-weight:600; letter-spacing:6px;'>" + esc(brandName.toUpperCase()) + '</div>',
  });

  scenes.push(sEnd);

  // ---- payload ------------------------------------------------------------
  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const safeName = ('listing-' + address + (city ? '-' + city : ''))
    .toLowerCase().normalize('NFKD').replace(/\p{M}/gu, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).replace(/-+$/, '');

  const payload = {
    name: safeName || 'property-listing',
    resolution: 'instagram-reel',
    frameRate: 30,
    backgroundColor: ink,
    outputFormat: 'mp4',
    scenes: scenes,
  };

  // NOTE: no `track` here — the render API rejects audios[].track.
  const musicUrl = clean(data.musicUrl);
  if (musicUrl) {
    payload.audios = [{ src: musicUrl, volume: Number(cfg.musicVolume == null ? 0.12 : cfg.musicVolume) }];
  }

  return {
    payload: payload,
    meta: {
      address: address,
      city: city || null,
      price: price || null,
      beds: beds || null,
      baths: baths || null,
      sqft: sqft || null,
      factsShown: facts.map(function (f) { return f.key; }),
      spotlightOrder: spotlights.slice(0, Math.max(0, photos.length - 1)).map(function (f) { return f.key; }),
      photoCount: photos.length,
      photoScenes: photoScenes,
      sceneCount: sceneCount,
      agentName: agentName || null,
      agentPhone: agentPhone || null,
      hasAgentPhoto: hasAgentPhoto,
      kenBurnsDepth: depth,
      kenBurnsDepthSoft: depthSoft,
      addrSize: addrSize,
      addrLines: addrLines,
      musicUrl: musicUrl || null,
      contactDomain: contactDomain || null,
      totalSeconds: totalSeconds,
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const listing = $input.first().json;
const built = buildProject(config, {
  address: listing.address,
  city: listing.city,
  price: listing.price,
  beds: listing.beds,
  baths: listing.baths,
  sqft: listing.sqft,
  photos: listing.photos,
  agentName: listing.agentName,
  agentPhone: listing.agentPhone,
  agentPhotoUrl: listing.agentPhotoUrl,
  musicUrl: listing.musicUrl,
});
built.meta.rowNumber = listing.rowNumber == null ? null : listing.rowNumber;
built.meta.recordId = listing.recordId == null ? null : listing.recordId;
built.meta.source = listing.source || 'sheet';
built.meta.musicSkippedReason = listing.musicSkippedReason || null;
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live. Nothing is
// written back, so the next real run picks the same listing.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    address: d.meta.address,
    city: d.meta.city,
    price: d.meta.price,
    photoCount: d.meta.photoCount,
    sceneCount: d.meta.sceneCount,
    agent: d.meta.agentName,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalSeconds,
    warnings: d.warnings,
    sheetRow: d.meta.rowNumber,
    sourceUpdated: false,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render and mark the listing done.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. In sheet mode the row is already marked done by
// this point; in Airtable mode the record id is remembered HERE - only after a
// successful render - so a failed render retries the same listing next time.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const source = String(cfg.source || 'sheet').toLowerCase();
if (source === 'airtable' && build.meta.recordId) {
  const staticData = $getWorkflowStaticData('global');
  const seen = Array.isArray(staticData.renderedListingIds) ? staticData.renderedListingIds : [];
  staticData.renderedListingIds = [String(build.meta.recordId)].concat(seen.filter((rid) => rid !== String(build.meta.recordId))).slice(0, 200);
}

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    source,
    address: build.meta.address,
    city: build.meta.city,
    price: build.meta.price,
    beds: build.meta.beds,
    baths: build.meta.baths,
    sqft: build.meta.sqft,
    photoCount: build.meta.photoCount,
    sceneCount: build.meta.sceneCount,
    agent: build.meta.agentName,
    agentPortrait: build.meta.hasAgentPhoto ? 'photo' : 'monogram',
    kenBurnsDepth: build.meta.kenBurnsDepth,
    music: build.meta.musicUrl ? 'on' : ('off - ' + (build.meta.musicSkippedReason || 'no musicUrl')),
    videoSeconds: build.meta.totalSeconds,
    creditsCharged: build.creditsRequired,
    sheetRow: build.meta.rowNumber,
    sheetStatus: source === 'sheet' ? cfg.statusDoneValue : null,
    recordId: build.meta.recordId,
  },
}];
